import numpy as np

# Semantic type IDs (from crafter engine)
WATER = 1
GRASS = 2
STONE = 3
PATH = 4
SAND = 5
TREE = 6
LAVA = 7
COAL = 8
IRON = 9
DIAMOND = 10
TABLE = 11
FURNACE = 12
PLAYER_ID = 13
COW = 14
ZOMBIE = 15
SKELETON = 16
ARROW = 17
PLANT = 18

# Action IDs
NOOP = 0
MOVE_LEFT = 1
MOVE_RIGHT = 2
MOVE_UP = 3
MOVE_DOWN = 4
DO = 5
SLEEP = 6
PLACE_STONE = 7
PLACE_TABLE = 8
PLACE_FURNACE = 9
PLACE_PLANT = 10
MAKE_WOOD_PICKAXE = 11
MAKE_STONE_PICKAXE = 12
MAKE_IRON_PICKAXE = 13
MAKE_WOOD_SWORD = 14
MAKE_STONE_SWORD = 15
MAKE_IRON_SWORD = 16

WALKABLE = frozenset({GRASS, PATH, SAND})
MONSTERS = frozenset({ZOMBIE, SKELETON})

_D2A = {(-1, 0): MOVE_LEFT, (1, 0): MOVE_RIGHT, (0, -1): MOVE_UP, (0, 1): MOVE_DOWN}
_DIRS = [(-1, 0), (1, 0), (0, -1), (0, 1)]


class CrafterHeuristicAgent:
    """Rule-based survival agent for Crafter using semantic map + inventory.

    Reads the full 64x64 semantic grid and player inventory each step.
    Deterministic given the same state (ties broken by seeded RNG).
    """

    def __init__(self, seed=42):
        self.rng = np.random.RandomState(seed)
        self.facing = (0, 1)

    def reset(self):
        self.facing = (0, 1)

    def act(self, obs_image, info):
        if not info or "semantic" not in info or "player_pos" not in info:
            return NOOP

        sem = info["semantic"]
        H, W = sem.shape
        px, py = int(info["player_pos"][0]), int(info["player_pos"][1])
        inv = info.get("inventory", {})

        health = inv.get("health", 9)
        food = inv.get("food", 9)
        drink = inv.get("drink", 9)
        energy = inv.get("energy", 9)

        has_sword = (
            inv.get("iron_sword", 0)
            or inv.get("stone_sword", 0)
            or inv.get("wood_sword", 0)
        )
        has_pickaxe = (
            inv.get("iron_pickaxe", 0)
            or inv.get("stone_pickaxe", 0)
            or inv.get("wood_pickaxe", 0)
        )
        wood = inv.get("wood", 0)
        stone = inv.get("stone", 0)

        adj_monsters = self._find_within(sem, H, W, px, py, MONSTERS, 2)
        touching = [(x, y) for x, y in adj_monsters if abs(x - px) + abs(y - py) == 1]

        # ── P1  FLEE when health critical ──
        if health <= 3 and touching:
            return self._flee(px, py, touching, sem, H, W)

        # ── P2  FIGHT adjacent monster if armed ──
        if touching and has_sword and health > 4:
            return self._face_pos(px, py, touching[0])

        # ── P3  FLEE adjacent monster when unarmed ──
        if touching and not has_sword:
            return self._flee(px, py, touching, sem, H, W)

        # ── P4  DRINK (critical) ──
        if drink <= 2:
            a = self._interact(px, py, sem, H, W, WATER)
            if a is not None:
                return a

        # ── P5  EAT (critical) ──
        if food <= 2:
            a = self._interact(px, py, sem, H, W, COW)
            if a is None:
                a = self._interact(px, py, sem, H, W, PLANT)
            if a is not None:
                return a

        # ── P6  SLEEP ──
        far_monsters = self._find_within(sem, H, W, px, py, MONSTERS, 8)
        if energy <= 1 and not far_monsters:
            return SLEEP

        # ── P7  DRINK (preventive) ──
        if drink <= 4:
            a = self._interact(px, py, sem, H, W, WATER)
            if a is not None:
                return a

        # ── P8  EAT (preventive) ──
        if food <= 4:
            a = self._interact(px, py, sem, H, W, COW)
            if a is None:
                a = self._interact(px, py, sem, H, W, PLANT)
            if a is not None:
                return a

        # ── P9  COLLECT WOOD ──
        if wood < 2:
            a = self._interact(px, py, sem, H, W, TREE)
            if a is not None:
                return a

        # ── P10  PLACE TABLE ──
        has_table = self._in_radius(sem, H, W, px, py, TABLE, 1)
        if not has_table and wood >= 2:
            fx, fy = px + self.facing[0], py + self.facing[1]
            if 0 <= fx < H and 0 <= fy < W and sem[fx, fy] in WALKABLE:
                return PLACE_TABLE
            return self._explore(px, py, sem, H, W)

        # ── P11  CRAFT TOOLS ──
        if has_table:
            if not inv.get("wood_pickaxe", 0) and wood >= 1:
                return MAKE_WOOD_PICKAXE
            if not inv.get("wood_sword", 0) and wood >= 1:
                return MAKE_WOOD_SWORD

        # ── P12  MORE WOOD ──
        if wood < 4:
            a = self._interact(px, py, sem, H, W, TREE)
            if a is not None:
                return a

        # ── P13  MINE STONE ──
        if has_pickaxe and stone < 2:
            a = self._interact(px, py, sem, H, W, STONE)
            if a is not None:
                return a

        # ── P14  UPGRADE TOOLS ──
        if has_table and stone >= 1 and wood >= 1:
            if not inv.get("stone_pickaxe", 0):
                return MAKE_STONE_PICKAXE
            if not inv.get("stone_sword", 0):
                return MAKE_STONE_SWORD

        # ── P15  MAINTENANCE ──
        if drink <= 6:
            a = self._interact(px, py, sem, H, W, WATER)
            if a is not None:
                return a
        if food <= 6:
            a = self._interact(px, py, sem, H, W, COW)
            if a is None:
                a = self._interact(px, py, sem, H, W, PLANT)
            if a is not None:
                return a

        # ── DEFAULT  EXPLORE ──
        return self._explore(px, py, sem, H, W)

    # ─────────────────── helpers ───────────────────

    def _find_within(self, sem, H, W, px, py, types, radius):
        if isinstance(types, (int, np.integer)):
            types = frozenset({int(types)})
        x0, x1 = max(0, px - radius), min(H, px + radius + 1)
        y0, y1 = max(0, py - radius), min(W, py + radius + 1)
        sub = sem[x0:x1, y0:y1]
        out = []
        for t in types:
            for lx, ly in np.argwhere(sub == t):
                gx, gy = int(lx) + x0, int(ly) + y0
                if abs(gx - px) + abs(gy - py) <= radius:
                    out.append((gx, gy))
        return out

    def _in_radius(self, sem, H, W, px, py, tid, r):
        x0, x1 = max(0, px - r), min(H, px + r + 1)
        y0, y1 = max(0, py - r), min(W, py + r + 1)
        return bool(np.any(sem[x0:x1, y0:y1] == tid))

    def _nearest(self, sem, px, py, tid):
        pts = np.argwhere(sem == tid)
        if len(pts) == 0:
            return None
        d = np.abs(pts[:, 0] - px) + np.abs(pts[:, 1] - py)
        i = int(np.argmin(d))
        return int(pts[i, 0]), int(pts[i, 1])

    def _interact(self, px, py, sem, H, W, tid):
        t = self._nearest(sem, px, py, tid)
        if t is None:
            return None
        tx, ty = t
        dist = abs(tx - px) + abs(ty - py)
        if dist == 0:
            return DO
        if dist == 1:
            d = (tx - px, ty - py)
            if self.facing == d:
                return DO
            self.facing = d
            return _D2A[d]
        return self._step_toward(px, py, tx, ty, sem, H, W)

    def _face_pos(self, px, py, pos):
        tx, ty = pos
        dx, dy = tx - px, ty - py
        if dx == 0 and dy == 0:
            return DO
        if abs(dx) >= abs(dy):
            d = (int(np.sign(dx)), 0)
        else:
            d = (0, int(np.sign(dy)))
        if self.facing == d:
            return DO
        self.facing = d
        return _D2A[d]

    def _step_toward(self, px, py, tx, ty, sem, H, W):
        dx, dy = int(np.sign(tx - px)), int(np.sign(ty - py))
        primary = []
        if abs(tx - px) >= abs(ty - py):
            if dx:
                primary.append((dx, 0))
            if dy:
                primary.append((0, dy))
        else:
            if dy:
                primary.append((0, dy))
            if dx:
                primary.append((dx, 0))
